  // ─────────────────────────────────────────────────────────
  // SECTION DATA: Tokenization examples
  // ─────────────────────────────────────────────────────────
  // Real BPE tokenization is complex; for teaching we use a heuristic
  // that matches the shape students would see in a tokenizer (sub-word
  // chunks for affixes, whole words for short common words).

  var COMMON_WORDS = { 'the':1,'a':1,'an':1,'is':1,'are':1,'was':1,'were':1,'and':1,'or':1,'but':1,'in':1,'on':1,'to':1,'of':1,'for':1,'with':1,'it':1,'that':1,'this':1,'be':1,'as':1,'at':1,'by':1,'from':1,'i':1,'you':1,'we':1,'he':1,'she':1,'they':1,'my':1,'me':1,'if':1,'not':1,'no':1,'yes':1,'do':1,'does':1,'did':1,'have':1,'has':1,'had':1,'can':1,'will':1,'would':1,'should':1,'sky':1,'blue':1,'red':1,'sun':1,'light':1,'day':1,'cat':1,'dog':1 };
  var PREFIXES = ['un','re','pre','dis','over','under','mis','non'];
  var SUFFIXES = ['ing','tion','sion','ment','ness','able','less','ful','ly','ed','er','est','ity','ous','ive'];

  // ── What this tokenizer will and will not do ─────────────────────────
  // The affix rules above were the ONLY thing that could split a word, and
  // they fired on any accidental substring match. "Emily" came out as Emi|ly
  // and "Christopher" as Christoph|er — neither of which is morphology —
  // while Nguyen, Oyelaran, Krzyzewski and Rodriguez each came out as one
  // clean token. Proper nouns now skip the affix rules entirely, which fixes
  // the false splits.
  //
  // What is deliberately NOT here is a rarity model. Real BPE fragments a
  // string according to how often it appeared in training data, and that is
  // not recoverable from spelling: Rodriguez and Adeyemi are built from
  // exactly the same ordinary English letter pairs, yet a real tokenizer
  // treats them very differently because one is far commoner in English text.
  // A letter-pattern heuristic was tried here and rejected — it scored
  // Rodriguez, Adeyemi and Oyelaran as maximally English, so it could not
  // have taught the thing it would have claimed to teach.
  //
  // The consequence is that this demo shows the SHAPE of subword tokenization
  // and nothing about how any particular name really tokenizes. The UI says
  // so, and the teacher note no longer asks the class to draw conclusions
  // from their own names in this widget.

  function pseudoTokenize(text) {
    // Produces an array of { tok, kind } entries where kind is
    // 'word' | 'subword' | 'space' | 'punct'.
    // This is a TEACHING tokenization — close enough in shape to real
    // subword tokenizers to make the mechanics visible.
    if (!text) return [];
    var out = [];
    var i = 0;
    while (i < text.length) {
      var ch = text.charAt(i);
      if (ch === ' ' || ch === '\n' || ch === '\t') {
        out.push({ tok: ch === '\n' ? '\u23CE' : '\u2423', kind: 'space' });
        i++; continue;
      }
      if (/[.,!?;:()"'\[\]\/-]/.test(ch)) {
        out.push({ tok: ch, kind: 'punct' });
        i++; continue;
      }
      // Read a word
      var j = i;
      while (j < text.length && /[\p{L}\p{M}\p{N}']/u.test(text.charAt(j)) ) j++;
      var word = text.substring(i, j);
      if (!word) {
        // A symbol or emoji: one token, keeping surrogate pairs and any
        // variation selector together. Must advance, or this loop never ends.
        var cp = text.codePointAt(i);
        var symEnd = i + (cp > 0xFFFF ? 2 : 1);
        if (text.charCodeAt(symEnd) === 0xFE0F) symEnd++;
        out.push({ tok: text.substring(i, symEnd), kind: 'punct' });
        i = symEnd;
        continue;
      }
      i = j;
      var lower = word.toLowerCase();
      if (COMMON_WORDS[lower] || word.length <= 3) {
        out.push({ tok: word, kind: 'word' });
        continue;
      }
      // A capitalised word that is not a common word is a name or other
      // proper noun. English affix rules must not touch it — that is what
      // turned Emily into Emi|ly and Christopher into Christoph|er. Send it
      // down the familiarity path instead, which is what a real tokenizer
      // effectively does with a string it has rarely seen.
      if (/^\p{Lu}/u.test(word)) {
        out.push({ tok: word, kind: 'word' });
        continue;
      }
      // Try prefix / suffix split
      var handled = false;
      for (var p = 0; p < PREFIXES.length && !handled; p++) {
        var pre = PREFIXES[p];
        if (lower.indexOf(pre) === 0 && word.length > pre.length + 2) {
          out.push({ tok: word.substring(0, pre.length), kind: 'subword' });
          var rest = word.substring(pre.length);
          // Check suffix on remainder
          var sufHit = null;
          for (var s = 0; s < SUFFIXES.length && !sufHit; s++) {
            var suf = SUFFIXES[s];
            if (rest.toLowerCase().endsWith(suf) && rest.length > suf.length + 1) sufHit = suf;
          }
          if (sufHit) {
            out.push({ tok: rest.substring(0, rest.length - sufHit.length), kind: 'subword' });
            out.push({ tok: rest.substring(rest.length - sufHit.length), kind: 'subword' });
          } else {
            out.push({ tok: rest, kind: 'subword' });
          }
          handled = true;
        }
      }
      if (handled) continue;
      // Suffix-only split
      for (var s2 = 0; s2 < SUFFIXES.length; s2++) {
        var suf2 = SUFFIXES[s2];
        if (lower.endsWith(suf2) && word.length > suf2.length + 2) {
          out.push({ tok: word.substring(0, word.length - suf2.length), kind: 'subword' });
          out.push({ tok: word.substring(word.length - suf2.length), kind: 'subword' });
          handled = true;
          break;
        }
      }
      // No morphology found. A lower-case word can still be an unfamiliar
      // string — a loanword, a transliteration, a technical term — so it gets
      // the same familiarity treatment rather than being assumed to be one
      // token just because English suffix rules did not recognise it.
      if (!handled) out.push({ tok: word, kind: 'word' });
    }
    return out;
  }

